local TailpieceMaker = {}
local PRODUCTS = {
    iron_tailpiece = { name = "Železni repnik za strune", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni repnik za strune za glasbila." },
    bronze_tailpiece = { name = "Bronast repnik za strune", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast repnik za strune za fino glasbo." },
    silver_tailpiece = { name = "Srebrn repnik za strune", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn repnik za strune za plemiške glasbenike." },
    gilded_tailpiece = { name = "Pozlačen repnik za strune", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen repnik za strune za dvorne glasbenike." },
    jewel_set_tailpiece = { name = "Draguljast repnik za strune", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast repnik za strune za kraljevske glasbenike." },
    royal_sovereign_tailpiece = { name = "Kraljevski suveren repnik za strune", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren repnik za strune z biseri za krono." },
}
local BUILDINGS = {
    tailpiece_workshop = { name = "Tailpiece delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    tailpiece_house = { name = "Tailpiece hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_tailpiece_atelier = { name = "Mojstrski tailpiece atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_tailpiece_palace = { name = "Suverena tailpiece palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
TailpieceMaker.ironStock = 14; TailpieceMaker.bronzeStock = 12; TailpieceMaker.woodStock = 14; TailpieceMaker.leatherStock = 10; TailpieceMaker.silverStock = 8; TailpieceMaker.goldStock = 6; TailpieceMaker.jewelStock = 4; TailpieceMaker.pearlStock = 4
TailpieceMaker.productStock = {}; TailpieceMaker.buildings = {}; TailpieceMaker.maker = nil; TailpieceMaker.activeMaking = {}; TailpieceMaker.totalProducts = 0; TailpieceMaker.dayTimer = 0
function TailpieceMaker.init() TailpieceMaker.ironStock=14; TailpieceMaker.bronzeStock=12; TailpieceMaker.woodStock=14; TailpieceMaker.leatherStock=10; TailpieceMaker.silverStock=8; TailpieceMaker.goldStock=6; TailpieceMaker.jewelStock=4; TailpieceMaker.pearlStock=4; TailpieceMaker.productStock={}; TailpieceMaker.buildings={}; TailpieceMaker.maker=nil; TailpieceMaker.activeMaking={}; TailpieceMaker.totalProducts=0; TailpieceMaker.dayTimer=0; print("[TailpieceMaker] Royal Tailpiece Maker System initialized (6 products, 4 buildings)") end
function TailpieceMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; TailpieceMaker.maker={name=n or ("Repnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Repnik najet: %s (spretnost: %d)",TailpieceMaker.maker.name,s),"success") end; return true end
function TailpieceMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function TailpieceMaker.build(id) local ok,e=TailpieceMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(TailpieceMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function TailpieceMaker.getQualityBonus() local b=0; for _,bd in ipairs(TailpieceMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function TailpieceMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and TailpieceMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and TailpieceMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and TailpieceMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and TailpieceMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and TailpieceMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and TailpieceMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and TailpieceMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and TailpieceMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #TailpieceMaker.buildings==0 then return false,"Potrebna repna delavnica" end; if not TailpieceMaker.maker then return false,"Potreben repnik" end; return true end
function TailpieceMaker.make(pt,qty) qty=qty or 1; local ok,e=TailpieceMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then TailpieceMaker.ironStock=TailpieceMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then TailpieceMaker.bronzeStock=TailpieceMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then TailpieceMaker.woodStock=TailpieceMaker.woodStock-d.woodCost*qty end; if d.leatherCost then TailpieceMaker.leatherStock=TailpieceMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then TailpieceMaker.silverStock=TailpieceMaker.silverStock-d.silverCost*qty end; if d.goldCost then TailpieceMaker.goldStock=TailpieceMaker.goldStock-d.goldCost*qty end; if d.jewelCost then TailpieceMaker.jewelStock=TailpieceMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then TailpieceMaker.pearlStock=TailpieceMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if TailpieceMaker.maker then t=math.max(1,t-math.floor(TailpieceMaker.maker.skill/13)) end; table.insert(TailpieceMaker.activeMaking,{id="tailpiece_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function TailpieceMaker.completeMaking(m) local q=1.0+(TailpieceMaker.getQualityBonus()/100); if TailpieceMaker.maker then q=q+(TailpieceMaker.maker.skill/140) end; q=math.min(2.5,q); TailpieceMaker.productStock[m.productType]=(TailpieceMaker.productStock[m.productType] or 0)+m.quantity; TailpieceMaker.totalProducts=TailpieceMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if TailpieceMaker.maker then TailpieceMaker.maker.itemsMade=TailpieceMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then TailpieceMaker.maker.skill=math.min(100,TailpieceMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Repnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"tailpiece.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function TailpieceMaker.update(dt) if not _G.state then return end; TailpieceMaker.dayTimer=TailpieceMaker.dayTimer+dt; if TailpieceMaker.dayTimer>=30 then TailpieceMaker.dayTimer=0; for i=#TailpieceMaker.activeMaking,1,-1 do local m=TailpieceMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then TailpieceMaker.completeMaking(m); table.remove(TailpieceMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(TailpieceMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if TailpieceMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function TailpieceMaker.getStats() return {ironStock=TailpieceMaker.ironStock,bronzeStock=TailpieceMaker.bronzeStock,woodStock=TailpieceMaker.woodStock,leatherStock=TailpieceMaker.leatherStock,silverStock=TailpieceMaker.silverStock,goldStock=TailpieceMaker.goldStock,jewelStock=TailpieceMaker.jewelStock,pearlStock=TailpieceMaker.pearlStock,productStock=TailpieceMaker.productStock,numBuildings=#TailpieceMaker.buildings,hasMaker=TailpieceMaker.maker~=nil,makerName=TailpieceMaker.maker and TailpieceMaker.maker.name or "—",makerSkill=TailpieceMaker.maker and TailpieceMaker.maker.skill or 0,activeMaking=#TailpieceMaker.activeMaking,totalProducts=TailpieceMaker.totalProducts} end
return TailpieceMaker
